<?php namespace App\Http\Controllers; use App\Http\Requests\StorePurchaseRequest;use App\Models\Product;use App\Models\Purchase;use App\Services\RecordPurchaseService;use Illuminate\Http\Request; class PurchaseController extends Controller { public function index(Request $r){$q=Purchase::query();foreach(['supplier_name','payment_status']as $f)if($r->$f)$q->where($f,$r->$f);if($r->from)$q->whereDate('purchase_date','>=',$r->from);if($r->to)$q->whereDate('purchase_date','<=',$r->to);return view('purchases.index',['purchases'=>$q->latest('purchase_date')->paginate(15)]);}public function create(){return view('purchases.form',['products'=>Product::where('status','active')->orderBy('name')->get()]);}public function store(StorePurchaseRequest $r,RecordPurchaseService $s){$p=$s->record($r->validated(),$r->user()->id);return redirect()->route('purchases.show',$p)->with('success','Purchase recorded.');}public function show(Purchase $purchase){$purchase->load('items.product');return view('purchases.show',compact('purchase'));} }